<?php require_once __DIR__.'/includes/bootstrap.php';require_manager();$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add'){$s=$pdo->prepare('INSERT INTO products(category_id,name,description,price) VALUES(?,?,?,?)');$s->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']),round((float)$_POST['price'],2)]);log_action('Product added',$_POST['name']);$msg='Product added.';}elseif($action==='toggle'){$s=$pdo->prepare('UPDATE products SET is_available=1-is_available WHERE id=?');$s->execute([(int)$_POST['id']]);$msg='Product availability updated.';}elseif($action==='price'){$s=$pdo->prepare('UPDATE products SET price=? WHERE id=?');$s->execute([max(0,(float)$_POST['price']),(int)$_POST['id']]);$msg='Product price updated.';}}
$cats=$pdo->query('SELECT * FROM categories WHERE is_active=1')->fetchAll();$products=$pdo->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY c.name,p.name')->fetchAll();$pageTitle='Menu & Products';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><h2>Add menu item</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><div><label>Product name</label><input name="name" required></div><div><label>Category</label><select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Price (USD)</label><input type="number" name="price" min="0" step="0.01" required></div><div><label>Description</label><input name="description"></div><div class="form-action"><button class="btn primary">Add product</button></div></form></div><div class="panel"><h2>Menu catalogue</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Availability</th><th>Update price</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=e($p['name'])?></b><small class="block muted"><?=e($p['description'])?></small></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?= $p['is_available']?'Available':'Unavailable'?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="price"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="number" name="price" min="0" step="0.01" value="<?=e($p['price'])?>" style="width:90px"><button class="btn small secondary">Save</button></form></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn small secondary">Toggle</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
